package com.rohit.inventory.entity; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="notifications") public class Notification extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="recipient_user_id",nullable=false) private User recipient; @Column(name="notification_type",nullable=false) private String notificationType; @Enumerated(EnumType.STRING) @Column(nullable=false) private Severity severity; @Column(nullable=false) private String title; @Column(nullable=false) private String message; @Column(name="related_entity_type") private String entityType; @Column(name="related_entity_id") private UUID entityId; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="warehouse_id") private Warehouse warehouse; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="product_id") private Product product; @Column(name="is_read",nullable=false) private boolean read; @Column(name="read_at") private Instant readAt; public enum Severity{INFO,SUCCESS,WARNING,CRITICAL} public UUID getId(){return super.getId();} public User getRecipient(){return recipient;} public String getNotificationType(){return notificationType;} public Severity getSeverity(){return severity;} public String getTitle(){return title;} public String getMessage(){return message;} public Warehouse getWarehouse(){return warehouse;} public Product getProduct(){return product;} public boolean isRead(){return read;} public Instant getReadAt(){return readAt;} public void setRecipient(User v){recipient=v;} public void setNotificationType(String v){notificationType=v;} public void setSeverity(Severity v){severity=v;} public void setTitle(String v){title=v;} public void setMessage(String v){message=v;} public void setEntityType(String v){entityType=v;} public void setEntityId(UUID v){entityId=v;} public void setWarehouse(Warehouse v){warehouse=v;} public void setProduct(Product v){product=v;} public void setRead(boolean v){read=v;} public void setReadAt(Instant v){readAt=v;} }
